"""Finite own-collet exclusion proof; no service sweep, CAD, native or routing."""
import argparse,json,math,hashlib,sys
from pathlib import Path
R=Path(__file__).resolve().parents[6];P=R/'circuit/routing/epic-242/decision-pilots/feed-arrangement';sys.path.insert(0,str(P))
import numpy as np
import robust_curve as rc
from clamps import exit_proof
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
saved=json.loads((P/'robust-curve.json').read_text());F=rc.Family();r=1.2954
assert saved['tool_sha256']==sha(P/'robust_curve.py')
assert saved['family']['offset_mm']==F.offset_mm==58
assert saved['family']['tail_each_mm']==F.tail_each_mm==2.5
assert saved['family']['free_length_range_mm']==list(F.free_length_range_mm)
g0,g1=F.gap_range;h0,h1=saved['reference_curve']['handle_range_mm'];h0-=1e-7;h1+=1e-7
# Global independent corner box is deliberately wider than the physically used g/h set.
controls=[rc.control(F,g,h) for g in [g0,g1] for h in [h0,h1]]
w0=np.asarray(F.direction);w1=w0*np.array([1,-1,1])
proof=exit_proof(controls,w0,w1,r)
speed=max(float(np.linalg.norm(q)) for p in controls for q in 3*np.diff(p,axis=0))+1e-9
reference_tangent_axial=proof['global_axial_derivative_lower']/speed
eta1=F.first_derivative_error_max;eta2=F.second_derivative_error_max_per_mm
Rref=saved['reference_curve']['radius_lower_bound_mm'];Ractual=(1-eta1)**2/(1/Rref+eta2)
kappa=1/Ractual;s0=2.;m=math.cos(kappa*s0)
actual_axial_derivative=reference_tangent_axial-eta1
assert actual_axial_derivative>0 and s0*kappa<math.pi/2 and m*m>r*kappa and s0*m>r
c=-F.direction[2];cmin=(c-eta1)/(1+eta1);insulation_clear=3.70*cmin-r*math.sqrt(1-cmin*cmin)
assert insulation_clear-.45>.25
out={'schema':'feed-v2-own-collet-exit-proof-v1','status':'PASS_REFERENCE_FAMILY; ACTUAL_FINITE_TUBE_PASS_CONDITIONAL_ON_BOUNDARY_AND_SHAPE_REQUIREMENTS','source_sha256':{str(p):sha(p) for p in [Path(__file__),P/'robust_curve.py',P/'robust-curve.json',P/'clamps.py']},'source_family':{'gap_mm':[g0,g1],'free_length_mm':list(F.free_length_range_mm),'independent_global_handle_box_mm':[h0,h1],'control_corners':4,'wire_radius_mm':r,'collet_outer_radius_mm':2,'grip_axis_stations_from_anchor_mm':[1,2.5],'same_proof_applies_to_wires':[1,2,3,4,5,6],'transform_scope':'Translations, orthogonal Y reflections and reversal preserve all norms/projections; both endpoints explicitly included in exit_proof.'},'reference_exclusion':proof,'reference_speed_upper_per_Bezier_parameter_mm':speed,'reference_unit_tangent_axial_projection_lower':reference_tangent_axial,'allowed_contact_mask':{'only_solids':'Same board and wire split_collet analytic finite cylinder, with bore radius>=actual wire radius and axial grip1..2.5; subtracting split slots only removes material.','allowed_contact':'Own straight wire occupies its own cylindrical bore. Boundary contact at bore/cylinder exit circle is allowed; no material overlap in annulus.','not_exempt':['Lug','M1 fasteners/nuts/caps','Fingers','Foreign collets','Foreign wires','PCB slabs','Shroud','Solder/foil outside separately declared own landing mask'],'near_exit_geometry':'With axial a>=m*t and transverse displacement rho<=M*t²/2, a²>=2*r*rho if m²>=r*M. This implies centre distance>=r to the entire annulus radius>=r behind the exit plane, so even a conservative spherical swept tube cannot penetrate that collet annulus. After t0, axial distance>r and stays increasing.','entry_side':'Before the free-curve exit the bridge/tail is straight on the measured bore axis. Metal<=1mm and insulation<=1.2954mm radii fit the declared bore; the occupied bore is an intended contact only.'},'actual_shape_extension':{'actual_radius_lower_if_C1_C2_hold_mm':Ractual,'actual_curve_registered_reference_axial_derivative_lower':actual_axial_derivative,'near_exit_actual_arclength_limit_mm':s0,'near_exit_axial_derivative_lower':m,'curvature_upper_per_mm':kappa,'m_squared_minus_r_kappa':m*m-r*kappa,'axial_at_s0_lower_mm':s0*m,'theorem':'At the actual flat exit register centreline point to the measured collet axis and tangent to that axis. Curvature<=kappa gives a(s)>=s*cos(kappa*s0), transverse rho(s)<=kappa*s²/2 for0<=s<=s0. Thus a²>=2*r*rho by reported inequality. Beyond s0, a>r and strict positive axial derivative follows from reference tangent lower minus|e_s|. Apply at both ends.','mandatory_boundary_requirements':['Actual straight gripped centreline lies on/within the measured bore containment mask through the flat exit; actual wire radius does not exceed measured bore radius.','For this sufficient proof the outgoing actual free-curve centre and unit tangent match the collet exit centre and axis in its registered frame. C0<=.20 and unrestricted C1 alone do NOT establish this boundary condition.','The complete actual centreline, including clamp transitions, satisfies the declared C1/C2 and material-length constraints. No merely positional point-cloud certificate.'],'scope':'Conditional sufficient physical-shape class; not a bench result or an assertion that unqualified hardware enforces exact exit matching. The reference source construction itself matches these endpoint conditions.'},'insulation_cut':{'station_range_from_land_mm':[3.70,3.80],'nominal_mm':3.75,'C1_normal_cosine_lower':cmin,'angle_and_cut_tolerance_board_gap_lower_mm':insulation_clear,'additional_closure_charged_mm':.45,'remaining_gap_mm':insulation_clear-.45,'required_residual_gap_mm':.25,'first_nominal_collet_grip_station_from_land_mm':2/c+1,'nominal_station_3p80_to_first_grip_mm':2/c+1-3.80,'scope':'Own terminal transition has an explicit mask and this residual-clearance calculation. Do not apply an unrelated free-wire nominal0.70mm threshold in addition to the already enumerated closure. Remaining individual fabrication effects must fit the0.45mm allocation; not measured capability.'},'integration_rule':'A checker may omit only the same-wire same-board split_collet pair after authenticating this proof and exact bore/grip/exit primitives. It must still check all other material and all straight/end segments. Unsupported shape/axis/bore edits invalidate the mask.','native':False,'sweep_executed':False}
ap=argparse.ArgumentParser();ap.add_argument('--output',type=Path,required=True);args=ap.parse_args();p=args.output;p.write_text(json.dumps(out,indent=2,sort_keys=True)+'\n');print(json.dumps({'path':str(p),'sha256':sha(p),'reference':proof,'actual_tangent_lower':actual_axial_derivative,'actual_near_margin':m*m-r*kappa,'insulation_remaining_mm':insulation_clear-.45},indent=2))
